/**
 * Settings → "Create recovery kit" (community edition, open-source step 5b): the account (blob v2 + the server it belongs
 * to) encrypted into an offline file with Argon2id over a strong passphrase (services/recoveryKit.ts).
 *
 * The passphrase is generated by default (125 bits, shown once, grouped by 5); the user may choose their own instead if
 * it passes the strength rule. Either way the user types it back before the kit is made, so a kit is never made with a
 * passphrase nobody wrote down. The kit is saved as a file (web: download; app: Files) and never sent anywhere.
 *
 * The PIN is asked last, and the kit is built only after it was checked (security review M2): an unlocked phone in
 * someone else's hands must not be enough to take the whole account away in a file with a passphrase of their choosing.
 * pinAuth().verifyPin counts wrong PINs and locks for 5 minutes after 5 of them (the same lock as the login screen).
 */
import { useState, useMemo } from 'react';
import { useCommunityStrings, type CommunityStringKey } from '../../i18n/communityStrings';
import { useLanguage } from '../../i18n';
import {
  createKit, generatePassphrase, normalizePassphrase, passphraseStrength, KitError,
} from '../../services/recoveryKit';
import { buildBlob } from '../../services/identityBlob';
import { activeServerForKit } from '../../services/serverChoice';
import { saveFile } from '../../services/fileOpener';
import { pinAuth } from '../../services/pinAuth';
import { readUnlockedIdentity } from './identityKeys';

type Step = 'pass' | 'confirm' | 'pin' | 'working' | 'done';

export type KitMakeResult = { ok: true; text: string } | { ok: false; reason: 'locked' | 'wrong_pin' | 'no_account' };

/** What building a kit needs (the real ones by default; tests pass their own). */
export const kitDeps = {
  isLockedOut: (): boolean => pinAuth().isLockedOut(),
  verifyPin: (pin: string): Promise<boolean> => pinAuth().verifyPin(pin),
  readIdentity: readUnlockedIdentity,
  buildBlob,
  createKit,
  server: activeServerForKit,
};

/** Check the PIN (with its lockout), then build the kit text. Nothing is read or encrypted before the PIN is right. */
export async function makeKitText(pin: string, passphrase: { value: string; generated: boolean }, deps = kitDeps): Promise<KitMakeResult> {
  if (deps.isLockedOut()) return { ok: false, reason: 'locked' };
  if (!(await deps.verifyPin(pin))) return { ok: false, reason: deps.isLockedOut() ? 'locked' : 'wrong_pin' };
  const identity = await deps.readIdentity();
  const blob = identity ? deps.buildBlob(identity) : null;
  if (!blob) return { ok: false, reason: 'no_account' };
  return { ok: true, text: await deps.createKit({ blob, server: deps.server() }, passphrase) };
}

export function kitFileName(now = new Date()): string {
  return `aegistalk-recovery-${now.toISOString().slice(0, 10)}.json`;
}

async function saveKitText(text: string): Promise<boolean> {
  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
  try {
    const r = await saveFile({ name: kitFileName(), mimeType: 'application/json', dataUrl: url });
    return r.success;
  } finally {
    setTimeout(() => URL.revokeObjectURL(url), 30_000);
  }
}

function RecoveryKitModal({ onClose }: { onClose: () => void }) {
  const s = useCommunityStrings();
  const { t } = useLanguage();
  const [pin, setPin] = useState('');
  const generated = useMemo(() => generatePassphrase(), []);
  const [own, setOwn] = useState(false);
  const [ownPass, setOwnPass] = useState('');
  const [retype, setRetype] = useState('');
  const [step, setStep] = useState<Step>('pass');
  const [error, setError] = useState('');
  const [kitText, setKitText] = useState<string | null>(null);

  const strength = passphraseStrength(ownPass);
  const passphrase = own ? ownPass : generated;
  const canContinue = own ? strength.ok : true;

  // passphrase typed back correctly → the PIN (last step)
  const toPin = () => {
    setError('');
    if (normalizePassphrase(retype, !own) !== normalizePassphrase(passphrase, !own)) {
      setError(s('kit.passMismatch'));
      return;
    }
    setPin('');
    setStep('pin');
  };

  const create = async () => {
    setError('');
    setStep('working');
    try {
      const made = await makeKitText(pin, { value: passphrase, generated: !own });
      setPin('');
      if (!made.ok) {
        setStep(made.reason === 'no_account' ? 'confirm' : 'pin');
        setError(made.reason === 'locked' ? t('auth.tooManyAttempts') : made.reason === 'wrong_pin' ? t('chatExport.wrongPin') : s('kit.failed'));
        return;
      }
      setKitText(made.text);
      setRetype('');
      await saveKitText(made.text);
      setStep('done');
    } catch (err) {
      setPin('');
      setStep('confirm');
      setError(err instanceof KitError ? s(`kit.err.${err.code}` as CommunityStringKey) : s('kit.failed'));
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4" role="dialog" aria-modal="true" data-testid="kit-export">
      <div className="w-full max-w-md bg-surface-secondary rounded-2xl p-5 space-y-4 max-h-[90dvh] overflow-y-auto">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-on-surface-primary">{s('kit.title')}</h2>
          <button onClick={onClose} disabled={step === 'working'} className="p-2 text-on-surface-secondary" aria-label={s('server.cancel')}>
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        <p className="text-sm text-on-surface-secondary">{s('kit.desc')}</p>

        {step === 'pass' && (
          <>
            {!own ? (
              <div className="space-y-2">
                <p className="text-sm text-on-surface-primary">{s('kit.passGenerated')}</p>
                <p className="font-mono text-lg tracking-wide text-on-surface-primary bg-surface-tertiary rounded-lg p-3 select-all break-all"
                   data-testid="kit-generated-pass">{generated}</p>
              </div>
            ) : (
              <div className="space-y-2">
                <label className="text-sm text-on-surface-secondary block" htmlFor="kit-own-pass">{s('kit.passOwnLabel')}</label>
                <input id="kit-own-pass" type="password" autoComplete="new-password" value={ownPass}
                  onChange={(e) => setOwnPass(e.target.value)}
                  className="w-full px-3 py-2 bg-surface-tertiary text-on-surface-primary rounded-lg border border-[var(--surface-border)]" />
                {ownPass && (
                  <p className={`text-xs ${strength.ok ? 'text-green-500' : 'text-red-400'}`}>
                    {strength.ok ? s('kit.strength', { bits: strength.bits }) : s(`kit.weak.${strength.reason}` as CommunityStringKey)}
                  </p>
                )}
              </div>
            )}
            <button type="button" onClick={() => { setOwn(!own); setOwnPass(''); }} className="text-accent text-sm">
              {own ? s('kit.passUseGenerated') : s('kit.passChooseOwn')}
            </button>
            <button type="button" disabled={!canContinue} onClick={() => setStep('confirm')}
              className="w-full py-3 rounded-xl bg-mist-500 text-white disabled:opacity-50">
              {s('kit.create')}
            </button>
          </>
        )}

        {step === 'confirm' && (
          <div className="space-y-2">
            <label className="text-sm text-on-surface-secondary block" htmlFor="kit-retype">{s('kit.passRetype')}</label>
            <input id="kit-retype" type={own ? 'password' : 'text'} autoComplete="off" autoCapitalize="off" spellCheck={false}
              value={retype} onChange={(e) => { setRetype(e.target.value); setError(''); }}
              className="w-full px-3 py-2 bg-surface-tertiary text-on-surface-primary rounded-lg border border-[var(--surface-border)] font-mono" />
            {error && <p className="text-sm text-red-400" role="alert">{error}</p>}
            <button type="button" disabled={!retype} onClick={toPin}
              className="w-full py-3 rounded-xl bg-mist-500 text-white disabled:opacity-50">
              {s('kit.create')}
            </button>
          </div>
        )}

        {step === 'pin' && (
          <div className="space-y-2">
            <label className="text-sm text-on-surface-secondary block" htmlFor="kit-pin">{t('auth.enterPin')}</label>
            <input id="kit-pin" type="password" inputMode="numeric" pattern="[0-9]*" maxLength={8} autoComplete="off" autoFocus
              value={pin} onChange={(e) => { setPin(e.target.value.replace(/\D/g, '')); setError(''); }}
              onKeyDown={(e) => { if (e.key === 'Enter' && pin.length >= 4) void create(); }}
              data-testid="kit-pin"
              className="w-full px-3 py-2 bg-surface-tertiary text-on-surface-primary rounded-lg border border-[var(--surface-border)] text-center tracking-[0.5em]" />
            {error && <p className="text-sm text-red-400" role="alert">{error}</p>}
            <button type="button" disabled={pin.length < 4} onClick={() => void create()}
              className="w-full py-3 rounded-xl bg-mist-500 text-white disabled:opacity-50">
              {s('kit.create')}
            </button>
          </div>
        )}

        {step === 'working' && <p className="text-sm text-on-surface-secondary">{s('kit.creating')}</p>}

        {step === 'done' && (
          <div className="space-y-3">
            <p className="text-sm text-green-500" data-testid="kit-saved">{s('kit.saved')}</p>
            <p className="text-xs text-on-surface-tertiary">{s('kit.stale')}</p>
            {kitText && (
              <button type="button" onClick={() => void saveKitText(kitText)} className="w-full py-2 rounded-xl bg-surface-tertiary text-on-surface-primary">
                {s('kit.saveAgain')}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/** Settings row (account block) + the modal */
export function RecoveryKitSettingsItem() {
  const s = useCommunityStrings();
  const [open, setOpen] = useState(false);
  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="w-full flex items-center justify-between p-3 mt-3 bg-surface-tertiary hover:opacity-80 rounded-lg transition-colors"
        data-testid="kit-export-open"
      >
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-primary-500/20 flex items-center justify-center">
            <svg className="w-5 h-5 text-accent" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
          </div>
          <div className="text-left">
            <p className="text-on-surface-primary text-sm font-medium">{s('kit.export')}</p>
            <p className="text-on-surface-secondary text-xs">{s('kit.desc')}</p>
          </div>
        </div>
      </button>
      {open && <RecoveryKitModal onClose={() => setOpen(false)} />}
    </>
  );
}
